arguments.file_text:
:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --ink: #16161a;
  --ink-2: #4a4a52;
  --muted: #8a8a92;
  --line: #ececea;
  --accent: #ff5a36;
  --accent-ink: #ffffff;
  --pill: #f1f1ee;
  --shadow: 0 1px 2px rgba(20,20,30,.04), 0 8px 24px rgba(20,20,30,.06);
  --radius: 14px;
  --radius-sm: 10px;
  --maxw: 1240px;
  --font: "Inter", "Helvetica Neue", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  --font-display: "Fraunces", "Times New Roman", Georgia, serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }
img { max-width: 100%; display: block; }

:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
  border-radius: 6px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: #fff;
  padding: 10px 16px;
  z-index: 1000;
  border-radius: 0 0 8px 0;
}
.skip-link:focus { left: 0; }

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---------- Announcement bar ---------- */
.announce {
  background: var(--ink);
  color: #f4f4ee;
  font-size: 13px;
  letter-spacing: .02em;
  padding: 10px 0;
  text-align: center;
}
.announce strong { color: #fff; font-weight: 600; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250,250,247,.92);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
  padding: 16px 0;
}
.brand {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 22px;
  letter-spacing: -.01em;
}
.brand .dot { color: var(--accent); }

.primary-nav ul {
  display: flex;
  gap: 28px;
  list-style: none;
  margin: 0;
  padding: 0;
  justify-content: center;
}
.primary-nav a {
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  padding: 6px 2px;
  position: relative;
}
.primary-nav a:hover { color: var(--ink); }
.primary-nav a[aria-current="page"] {
  color: var(--ink);
}
.primary-nav a[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -2px;
  height: 2px;
  background: var(--ink);
  border-radius: 2px;
}

.header-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  align-items: center;
}
.icon-btn {
  width: 40px;
  height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  color: var(--ink);
  position: relative;
}
.icon-btn:hover {
  background: var(--surface);
  border-color: var(--line);
}
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ---------- Hero ---------- */
.hero {
  padding: 36px 0 56px;
}
.hero-card {
  position: relative;
  background:
    radial-gradient(800px 360px at 80% 20%, rgba(255,90,54,.18), transparent 60%),
    linear-gradient(180deg, #f3efe7 0%, #ece6d9 100%);
  border-radius: 24px;
  overflow: hidden;
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  min-height: 520px;
}
.hero-content {
  padding: 64px 56px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 22px;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 500;
  color: var(--ink);
  background: rgba(255,255,255,.7);
  padding: 6px 12px;
  border-radius: 999px;
  width: fit-content;
}
.hero-eyebrow .pulse {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 0 rgba(255,90,54,.6);
  animation: pulse 1.8s infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(255,90,54,.6); }
  70% { box-shadow: 0 0 0 10px rgba(255,90,54,0); }
  100% { box-shadow: 0 0 0 0 rgba(255,90,54,0); }
}
.hero-title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(40px, 5.2vw, 68px);
  line-height: 1.02;
  letter-spacing: -.02em;
  margin: 0;
}
.hero-title em {
  font-style: italic;
  color: var(--accent);
}
.hero-sub {
  font-size: 17px;
  color: var(--ink-2);
  max-width: 460px;
  margin: 0;
}
.hero-cta {
  display: flex;
  gap: 12px;
  margin-top: 6px;
  flex-wrap: wrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: .01em;
  transition: transform .15s ease, background .2s ease, color .2s ease, border-color .2s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--ink);
  color: #fff;
}
.btn-primary:hover { background: #2a2a30; }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-ghost:hover { background: var(--ink); color: #fff; }

.hero-stats {
  display: flex;
  gap: 36px;
  margin-top: 18px;
}
.hero-stat .num {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 600;
  letter-spacing: -.01em;
}
.hero-stat .label {
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .12em;
}

.hero-visual {
  position: relative;
  background:
    linear-gradient(160deg, #d5c8b1 0%, #b9a78a 100%);
}
.hero-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(420px 420px at 30% 30%, rgba(255,255,255,.35), transparent 60%),
    radial-gradient(300px 300px at 80% 80%, rgba(0,0,0,.18), transparent 60%);
}
.hero-product-card {
  position: absolute;
  bottom: 28px;
  left: 28px;
  right: 28px;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(8px);
  border-radius: 16px;
  padding: 16px 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: var(--shadow);
  z-index: 1;
}
.hero-product-card .swatches {
  display: flex; gap: 6px;
}
.swatch {
  width: 18px; height: 18px; border-radius: 50%;
  border: 2px solid #fff;
  box-shadow: 0 0 0 1px rgba(0,0,0,.08);
}
.hero-product-card .meta {
  flex: 1;
}
.hero-product-card .name {
  font-weight: 600; font-size: 14px;
}
.hero-product-card .price {
  font-size: 13px; color: var(--ink-2);
}
.hero-product-card .price s { color: var(--muted); margin-right: 6px; }

.hero-illustration {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 0;
}

/* ---------- Categories ---------- */
.category-strip {
  padding: 8px 0 56px;
}
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.cat {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px 14px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  transition: transform .15s ease, box-shadow .2s ease, border-color .2s ease;
}
.cat:hover {
  transform: translateY(-2px);
  border-color: #d9d9d4;
  box-shadow: var(--shadow);
}
.cat-icon {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--pill);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.cat-name { font-weight: 600; font-size: 14px; }
.cat-count { font-size: 12px; color: var(--muted); }

/* ---------- Section headers ---------- */
.section { padding: 24px 0 56px; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}
.section-eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--accent);
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(28px, 3vw, 40px);
  letter-spacing: -.01em;
  font-weight: 500;
  margin: 6px 0 0;
}
.section-link {
  font-size: 14px;
  font-weight: 600;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}

/* ---------- Tabs ---------- */
.tabs {
  display: flex;
  gap: 6px;
  background: var(--pill);
  padding: 4px;
  border-radius: 999px;
  width: fit-content;
}
.tab {
  border: 0;
  background: transparent;
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  color: var(--ink-2);
}
.tab[aria-selected="true"] {
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow);
}

/* ---------- Product Grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.product {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .2s ease, box-shadow .25s ease, border-color .2s ease;
  position: relative;
}
.product:hover {
  transform: translateY(-3px);
  border-color: #d9d9d4;
  box-shadow: var(--shadow);
}
.product-media {
  aspect-ratio: 4 / 5;
  position: relative;
  overflow: hidden;
  background: #f3f1ec;
}
.product-media svg, .product-media .ph {
  width: 100%; height: 100%;
  display: block;
}
.product-badges {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; gap: 6px;
  z-index: 2;
}
.badge {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 2px rgba(0,0,0,.06);
}
.badge.sale { background: var(--accent); color: var(--accent-ink); }
.badge.new { background: var(--ink); color: #fff; }

.wishlist {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,.9);
  border: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  color: var(--ink-2);
  transition: color .2s ease, transform .15s ease;
}
.wishlist:hover { color: var(--accent); }
.wishlist[aria-pressed="true"] { color: var(--accent); }
.wishlist[aria-pressed="true"] svg { fill: currentColor; }

.product-body {
  padding: 14px 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.product-cat {
  font-size: 11px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--muted);
}
.product-name {
  font-size: 15px;
  font-weight: 600;
  margin: 0;
}
.product-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 6px;
}
.price-block {
  display: flex; align-items: baseline; gap: 8px;
}
.price-now { font-weight: 600; font-size: 15px; }
.price-was { color: var(--muted); text-decoration: line-through; font-size: 13px; }
.rating {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--ink-2);
}

.add-btn {
  margin-top: 12px;
  background: var(--ink);
  color: #fff;
  border: 0;
  padding: 10px 14px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: background .2s ease;
}
.add-btn:hover { background: var(--accent); }
.add-btn[data-added="true"] { background: #1f7a4d; }

/* ---------- Deals ---------- */
.deals {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 20px;
}
.deal-card {
  border-radius: var(--radius);
  padding: 28px;
  color: var(--ink);
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
}
.deal-card.lg { min-height: 360px; padding: 36px; }
.deal-card .tag {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  background: rgba(255,255,255,.6);
  padding: 5px 10px;
  border-radius: 999px;
  width: fit-content;
}
.deal-card h3 {
  font-family: var(--font-display);
  font-size: clamp(24px, 2.6vw, 36px);
  font-weight: 500;
  letter-spacing: -.01em;
  margin: 14px 0 8px;
  line-height: 1.05;
}
.deal-card p {
  margin: 0 0 18px;
  color: var(--ink-2);
  max-width: 36ch;
}
.deal-card .deal-cta {
  font-size: 14px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
  width: fit-content;
}

.deal-1 {
  background:
    radial-gradient(circle at 80% 20%, #ffd5c8, transparent 55%),
    linear-gradient(135deg, #fff1ea, #ffd9c9);
}
.deal-2 {
  background:
    radial-gradient(circle at 30% 80%, #c9d6ff, transparent 55%),
    linear-gradient(135deg, #ecf0ff, #d4ddff);
}
.deal-3 {
  background:
    radial-gradient(circle at 70% 30%, #cfe9d8, transparent 55%),
    linear-gradient(135deg, #e7f3ec, #c8e1d3);
}

/* Countdown */
.countdown {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}
.cd-cell {
  background: rgba(0,0,0,.85);
  color: #fff;
  border-radius: 10px;
  padding: 8px 10px;
  min-width: 56px;
  text-align: center;
}
.cd-cell .v {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 22px;
  display: block;
  font-variant-numeric: tabular-nums;
}
.cd-cell .l {
  font-size: 10px;
  color: rgba(255,255,255,.7);
  letter-spacing: .12em;
  text-transform: uppercase;
}

/* ---------- Editorial ---------- */
.editorial {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.article {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .2s ease, box-shadow .25s ease;
}
.article:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
.article-media {
  aspect-ratio: 16 / 11;
  background: #efece5;
  position: relative;
  overflow: hidden;
}
.article-media svg { width: 100%; height: 100%; display: block; }
.article-body { padding: 22px 22px 26px; }
.article-meta {
  display: flex; gap: 10px;
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .12em;
  margin-bottom: 10px;
}
.article-meta .pill {
  background: var(--pill);
  color: var(--ink);
  padding: 3px 9px;
  border-radius: 999px;
  letter-spacing: .08em;
}
.article-title {
  font-family: var(--font-display);
  font-size: 22px;
  letter-spacing: -.01em;
  font-weight: 500;
  margin: 0 0 10px;
  line-height: 1.2;
}
.article-excerpt { color: var(--ink-2); font-size: 14px; margin: 0 0 14px; }
.article-link { font-weight: 600; font-size: 14px; border-bottom: 1px solid currentColor; padding-bottom: 2px; }

/* ---------- Newsletter / Trust ---------- */
.newsletter {
  background: var(--ink);
  color: #f4f4ee;
  border-radius: 24px;
  padding: 56px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 3vw, 42px);
  font-weight: 500;
  letter-spacing: -.01em;
  margin: 0 0 8px;
  line-height: 1.05;
}
.newsletter p { margin: 0; color: rgba(244,244,238,.7); max-width: 42ch; }

.nl-form {
  display: flex;
  gap: 8px;
  background: rgba(255,255,255,.08);
  padding: 6px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.14);
}
.nl-form input {
  flex: 1;
  background: transparent;
  border: 0;
  color: #fff;
  padding: 12px 18px;
  font: inherit;
  outline: none;
}
.nl-form input::placeholder { color: rgba(244,244,238,.5); }
.nl-form button {
  background: #fff;
  color: var(--ink);
  border: 0;
  padding: 12px 20px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
}
.nl-form button:hover { background: var(--accent); color: #fff; }
.nl-msg {
  margin-top: 10px;
  font-size: 13px;
  color: rgba(244,244,238,.7);
  min-height: 18px;
}

.trust {
  padding: 40px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.trust-item {
  display: flex; gap: 14px; align-items: center;
}
.trust-icon {
  width: 44px; height: 44px;
  background: var(--pill);
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.trust-text strong { display: block; font-size: 14px; }
.trust-text span { font-size: 13px; color: var(--muted); }

/* ---------- Footer ---------- */
.site-footer {
  padding: 56px 0 28px;
}
.foot-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr 1fr;
  gap: 32px;
  margin-bottom: 36px;
}
.foot-brand p { color: var(--ink-2); max-width: 32ch; margin: 12px 0 18px; }
.socials { display: flex; gap: 8px; }
.foot-col h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .12em;
  margin: 6px 0 14px;
}
.foot-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; }
.foot-col a { color: var(--ink-2); font-size: 14px; }
.foot-col a:hover { color: var(--ink); }
.foot-bottom {
  border-top: 1px solid var(--line);
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 13px;
  flex-wrap: wrap;
  gap: 12px;
}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  right: 20px;
  bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 200;
