// Ecommerce home page — React-style components via React 18 (UMD) + Babel.
const { useState, useEffect, useMemo, useRef, useCallback } = React;

/* ------------------------- Icons ------------------------- */
const Icon = ({ name, size = 18, stroke = 1.6 }) => {
  const common = {
    width: size, height: size, viewBox: "0 0 24 24",
    fill: "none", stroke: "currentColor", strokeWidth: stroke,
    strokeLinecap: "round", strokeLinejoin: "round",
    "aria-hidden": "true", focusable: "false"
  };
  switch (name) {
    case "search": return <svg {...common}><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>;
    case "user": return <svg {...common}><circle cx="12" cy="8" r="4"/><path d="M4 21c1.5-4 5-6 8-6s6.5 2 8 6"/></svg>;
    case "heart": return <svg {...common}><path d="M12 21s-7-4.534-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.466-9.5 9-9.5 9z"/></svg>;
    case "bag": return <svg {...common}><path d="M6 7h12l-1 13a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L6 7z"/><path d="M9 7a3 3 0 0 1 6 0"/></svg>;
    case "arrow": return <svg {...common}><path d="M5 12h14"/><path d="m13 6 6 6-6 6"/></svg>;
    case "star": return <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false"><path d="M12 2.5l2.9 6.3 6.9.8-5.1 4.7 1.4 6.8L12 17.8l-6.1 3.3 1.4-6.8L2.2 9.6l6.9-.8L12 2.5z"/></svg>;
    case "truck": return <svg {...common}><path d="M3 7h11v9H3z"/><path d="M14 10h4l3 3v3h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/></svg>;
    case "return": return <svg {...common}><path d="M3 7v6h6"/><path d="M3 13a9 9 0 1 0 3-7"/></svg>;
    case "shield": return <svg {...common}><path d="M12 3l8 3v6c0 5-3.5 8.5-8 9-4.5-.5-8-4-8-9V6l8-3z"/><path d="m9 12 2 2 4-4"/></svg>;
    case "leaf": return <svg {...common}><path d="M20 4c0 8-5 14-14 14"/><path d="M20 4C8 4 4 10 4 18"/></svg>;
    case "menu": return <svg {...common}><path d="M4 7h16"/><path d="M4 12h16"/><path d="M4 17h16"/></svg>;
    case "ig": return <svg {...common}><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".8" fill="currentColor"/></svg>;
    case "x": return <svg {...common}><path d="M4 4l16 16"/><path d="M20 4 4 20"/></svg>;
    case "yt": return <svg {...common}><rect x="3" y="6" width="18" height="12" rx="3"/><path d="m11 10 4 2-4 2z" fill="currentColor"/></svg>;
    case "pin": return <svg {...common}><circle cx="12" cy="12" r="9"/><path d="M11 7v10"/><path d="M11 7c3 0 4 2 4 4s-1 4-4 4"/></svg>;
    case "check": return <svg {...common}><path d="m5 13 4 4L19 7"/></svg>;
    default: return null;
  }
};

