const useCountdown = (target) => {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, target - now);
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff / 3600000) % 24);
  const m = Math.floor((diff / 60000) % 60);
  const s = Math.floor((diff / 1000) % 60);
  return { d, h, m, s };
};

const Countdown = () => {
  const target = useMemo(() => Date.now() + (2 * 86400000) + (5 * 3600000) + (12 * 60000), []);
  const { d, h, m, s } = useCountdown(target);
  const cells = [["Days", d], ["Hrs", h], ["Min", m], ["Sec", s]];
  return (
    <div className="countdown" role="timer" aria-label={`Sale ends in ${d} days, ${h} hours, ${m} minutes, ${s} seconds`}>
      {cells.map(([l, v]) => (
        <div className="cd-cell" key={l}>
          <span className="v">{String(v).padStart(2, "0")}</span>
          <span className="l">{l}</span>
        </div>
      ))}
    </div>
  );
};

