    {toasts.map(t => (
      <div className="toast" key={t.id}>
        <span className="ok" aria-hidden="true"><Icon name="check"/></span>
        <span>{t.text}</span>
      </div>
    ))}
  </div>
);

/* ------------------------- App ------------------------- */
const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [toasts, setToasts] = useState([]);

  const pushToast = useCallback((text) => {
    const id = Math.random().toString(36).slice(2);
    setToasts(t => [...t, { id, text }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 2200);
  }, []);

  const addToCart = useCallback((p) => {
    setCart(c => [...c, p.id]);
    pushToast(`Added "${p.name}" to your cart`);
  }, [pushToast]);

  const toggleWish = useCallback((id) => {
    setWishlist(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);
  }, []);

  return (
    <>
      <a href="#main" className="skip-link">Skip to main content</a>
      <Announcement/>
      <Header cartCount={cart.length} onSearchToggle={() => pushToast("Search coming soon")}/>
      <main id="main">
        <Hero/>
        <Categories/>
        <Featured onAdd={addToCart} wishlist={wishlist} onWish={toggleWish}/>
        <Deals/>
        <Editorial/>
        <Trust/>
        <Newsletter/>
      </main>
      <Footer/>
      <ToastRegion toasts={toasts}/>
    </>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App/>);

